#!/usr/bin/env node
// Vector kit, web edition. One script, three commands:
//
//   node scripts/vector-web.mjs gen     tokens.json -> src/vector/tokens.css, ionicons -> src/vector/icon-paths.ts
//   node scripts/vector-web.mjs pull    copy the canonical kit's tokens.json in, then gen
//   node scripts/vector-web.mjs check   fail when the generated files are stale; warn when the kit has moved on
//
// src/vector/tokens.json is a snapshot of vector-design/kit/src/vector/tokens.json. Never edit it here: change the
// kit, then `pull`. The native kit emits HeroUI/Uniwind CSS; this emits plain CSS custom properties plus a Tailwind v4
// `@theme` block, so utilities like bg-surface, text-muted, border-border-strong and text-tint resolve to the tokens.

import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const tokensPath = join(root, "src/vector/tokens.json");
const cssPath = join(root, "src/vector/tokens.css");
const iconsPath = join(root, "src/vector/icon-paths.ts");
const kitTokensPath = resolve(root, "../vector-design/kit/src/vector/tokens.json");

/** Semantic glyphs the site uses: the kit's registry keys and their Ionicons names (src/vector/icons.ts in the kit). */
const ICONS = {
  add: "add",
  remove: "remove",
  close: "close",
  back: "chevron-back",
  forward: "chevron-forward",
  down: "chevron-down",
  menu: "menu-outline",
  more: "ellipsis-horizontal",
  check: "checkmark",
  done: "checkmark-circle",
  over: "alert-circle",
  info: "information-circle-outline",
  warning: "warning-outline",
  date: "calendar-outline",
  time: "time-outline",
  timer: "timer-outline",
  sync: "sync",
  camera: "camera-outline",
  scan: "barcode-outline",
  scanText: "scan-outline",
  analysis: "sparkles-outline",
  settings: "settings-outline",
  share: "share-outline",
  external: "open-outline",
  record: "trophy-outline",
  chart: "analytics-outline",
  history: "time-outline",
  weight: "barbell-outline",
  lift: "barbell-outline",
  food: "restaurant-outline",
  water: "water-outline",
  coffee: "cafe-outline",
  alcohol: "wine-outline",
  energy: "flash-outline",
  health: "heart-outline",
  photo: "image-outline",
  swap: "swap-horizontal",
  link: "link-outline",
  repeat: "repeat",
  tools: "construct-outline",
  document: "document-text-outline",
  travel: "airplane-outline",
  mic: "mic-outline",
  download: "download-outline",
  scale: "scale-outline",
  help: "help-circle-outline",
  lock: "lock-closed-outline",
  cloud: "cloud-outline",
  offline: "cloud-offline-outline",
  phone: "phone-portrait-outline",
  watch: "watch-outline",
  globe: "globe-outline",
  person: "person-outline",
  language: "language-outline",
  calculator: "calculator-outline",
  pulse: "pulse-outline",
  ruler: "resize-outline",
  key: "key-outline",
  notification: "notifications-outline",
  speedometer: "speedometer-outline",
};
/** Glyphs that flip under RTL (the kit's `mirrors`). */
const MIRRORS = ["back", "forward", "external"];

const banner = (what) =>
  `GENERATED by scripts/vector-web.mjs from ${what}. Do not edit: change the kit, then \`pnpm tokens:pull\`.`;

function cssValue(v) {
  return typeof v === "string" && v.startsWith("@") ? `var(--${v.slice(1)})` : v;
}

function block(selector, decls, indent = "") {
  const body = decls.map(([k, v]) => `${indent}  --${k}: ${v};`).join("\n");
  return `${indent}${selector} {\n${body}\n${indent}}`;
}

function genCss(tokens) {
  const colors = Object.entries(tokens.color);
  const pick = (mode) =>
    colors.filter(([, c]) => c[mode] !== undefined).map(([k, c]) => [k, cssValue(c[mode])]);
  const light = pick("light");
  const dark = pick("dark");
  const hcLight = pick("hcLight");
  const hcDark = pick("hcDark");
  const isShadow = (k) => k.endsWith("shadow");

  const theme = [
    // Only kit colours exist: app code cannot reach for a Tailwind palette hex.
    "  --color-*: initial;",
    "  --color-white: #FFFFFF;",
    ...colors.filter(([k]) => !isShadow(k)).map(([k]) => `  --color-${k}: var(--${k});`),
    // HeroUI-derived pressed states, mixed in OKLab as the browser does (design-system §2.2 web pins).
    "  --color-accent-hover: color-mix(in oklab, var(--accent) 90%, var(--accent-foreground) 10%);",
    "  --color-warning-hover: color-mix(in oklab, var(--warning) 90%, black);",
    "  --color-field-hover: var(--surface-secondary);",
    "  --color-backdrop: var(--backdrop);",
    "",
    "  --shadow-*: initial;",
    "  --shadow-overlay: var(--overlay-shadow);",
    "",
    "  --radius-*: initial;",
    ...Object.entries(tokens.radius).map(([k, v]) => `  --${k === "radius" ? "radius" : k}: ${v}px;`),
    "",
    "  --text-*: initial;",
    ...Object.entries(tokens.text).flatMap(([k, [size, line]]) => [
      `  --text-${k}: ${size}px;`,
      `  --text-${k}--line-height: ${line}px;`,
    ]),
    "",
    `  --tracking-tight: ${tokens.tracking.tight};`,
    `  --tracking-label: ${tokens.tracking.label};`,
    "",
    "  --font-*: initial;",
    '  --font-sans: var(--font-inter), "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;',
    '  --font-mono: var(--font-plex-mono), "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;',
    "",
    `  --opacity-disabled: ${tokens.static["opacity-disabled"]};`,
    "",
    "  --container-form: 640px;",
    "  --container-data: 1040px;",
    "",
    "  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);",
    "  --ease-exit: cubic-bezier(0.4, 0, 1, 1);",
    "  --animate-*: initial;",
  ];

  return [
    `/* ${banner(`src/vector/tokens.json (kit ${tokens.version})`)} */`,
    "",
    "/* Light is the default; dark follows the system unless the visitor picked an appearance (data-theme). */",
    block(":root", [["kit-version", `"${tokens.version}"`], ...light]),
    "",
    "@media (prefers-color-scheme: dark) {",
    block(':root:not([data-theme="light"])', dark, "  "),
    "}",
    block(':root[data-theme="dark"]', dark),
    "",
    "/* Increase Contrast: browsers report it as prefers-contrast: more (design-system §2.7). */",
    "@media (prefers-contrast: more) {",
    block(":root", hcLight, "  "),
    "}",
    "@media (prefers-contrast: more) and (prefers-color-scheme: dark) {",
    block(':root:not([data-theme="light"])', hcDark, "  "),
    "}",
    "@media (prefers-contrast: more) {",
    block(':root[data-theme="dark"]', hcDark, "  "),
    "}",
    "",
    ':root { color-scheme: light; }',
    '@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { color-scheme: dark; } }',
    ':root[data-theme="dark"] { color-scheme: dark; }',
    "",
    "@theme {",
    ...theme,
    "}",
    "",
  ].join("\n");
}

function genIcons() {
  const dir = join(root, "node_modules/ionicons/dist/svg");
  if (!existsSync(dir)) throw new Error("ionicons is not installed (pnpm install)");
  const entries = Object.entries(ICONS).map(([key, ion]) => {
    const svg = readFileSync(join(dir, `${ion}.svg`), "utf8");
    const inner = svg
      .replace(/^<svg[^>]*>/, "")
      .replace(/<\/svg>\s*$/, "")
      .replace(/<title>.*?<\/title>/g, "")
      .replace(/ class="[^"]*"/g, "")
      .trim();
    return `  ${key}: ${JSON.stringify(inner)},`;
  });
  return [
    `// ${banner("ionicons/dist/svg (MIT), the kit's default renderer")}`,
    "// Inner markup of each glyph on a 512 viewBox; strokes and fills use currentColor.",
    "",
    "export const iconPaths = {",
    ...entries,
    "} as const;",
    "",
    "export type IconName = keyof typeof iconPaths;",
    "",
    `export const mirroredIcons: ReadonlySet<IconName> = new Set(${JSON.stringify(MIRRORS)});`,
    "",
  ].join("\n");
}

const hash = (s) => createHash("sha256").update(s).digest("hex").slice(0, 12);

function gen({ write }) {
  const tokens = JSON.parse(readFileSync(tokensPath, "utf8"));
  const outputs = [
    [cssPath, genCss(tokens)],
    [iconsPath, genIcons()],
  ];
  const stale = [];
  for (const [path, content] of outputs) {
    const current = existsSync(path) ? readFileSync(path, "utf8") : "";
    if (current === content) continue;
    if (write) writeFileSync(path, content);
    else stale.push(path.replace(root + "/", ""));
  }
  return { tokens, stale };
}

const cmd = process.argv[2] ?? "gen";
if (cmd === "pull") {
  if (!existsSync(kitTokensPath)) {
    console.error(`No kit at ${kitTokensPath}`);
    process.exit(1);
  }
  writeFileSync(tokensPath, readFileSync(kitTokensPath));
  const { tokens } = gen({ write: true });
  console.log(`Pulled kit ${tokens.version} tokens and regenerated.`);
} else if (cmd === "gen") {
  const { tokens } = gen({ write: true });
  console.log(`Generated tokens.css and icon-paths.ts from kit ${tokens.version}.`);
} else if (cmd === "check") {
  const { tokens, stale } = gen({ write: false });
  if (stale.length) {
    console.error(`Stale generated files: ${stale.join(", ")}. Run \`pnpm tokens\`.`);
    process.exit(1);
  }
  if (existsSync(kitTokensPath)) {
    const local = readFileSync(tokensPath, "utf8");
    const kit = readFileSync(kitTokensPath, "utf8");
    if (hash(local) !== hash(kit)) {
      const kitVersion = JSON.parse(kit).version;
      console.warn(
        `Warning: tokens.json (kit ${tokens.version}) differs from the canonical kit (${kitVersion}). Run \`pnpm tokens:pull\`.`
      );
    }
  }
  console.log(`Vector web kit ${tokens.version}: generated files are current.`);
} else {
  console.error(`Unknown command ${cmd}. Use gen, pull or check.`);
  process.exit(1);
}
